<pre class="code">if (logger.isDebugEnabled()) {
  String str = logger.isTraceEnabled() ? "..." : "...";
  if (logger.isTraceEnabled()) {
    logger.trace(str);
  }
  else {
    logger.debug(str);
  }
}
</pre>
